//! Generated / minified file detection (upstream `generated-detection.ts`). A relevance
//! hint: generated nodes stay in the graph but rank last.

use regex::{Regex, RegexSet};
use std::sync::OnceLock;

fn path_set() -> &'static RegexSet {
    static SET: OnceLock<RegexSet> = OnceLock::new();
    SET.get_or_init(|| {
        RegexSet::new([
            r"\.pb\.go$",
            r"\.pulsar\.go$",
            r"_grpc\.pb\.go$",
            r"_mock\.go$",
            r"_mocks\.go$",
            r"^mock_[^/]+\.go$",
            r"\.generated\.[jt]sx?$",
            r"\.gen\.[jt]sx?$",
            r"\.pb\.[jt]s$",
            r"_pb\.[jt]s$",
            r"_grpc_pb\.[jt]s$",
            r"[.-]min\.[cm]?js$",
            r"_pb2(_grpc)?\.py$",
            r"_pb2\.pyi$",
            r"\.pb\.(cc|h)$",
            r"\.g\.cs$",
            r"Grpc\.cs$",
            r"OuterClass\.java$",
            r"Grpc\.java$",
            r"\.pb\.swift$",
            r"\.g\.dart$",
            r"\.freezed\.dart$",
            r"\.pb\.dart$",
            r"\.pbgrpc\.dart$",
            r"\.chopper\.dart$",
            r"\.generated\.rs$",
        ])
        .expect("generated path patterns")
    })
}

/// Path-only check (cheap enough for a sort comparator).
pub fn is_generated_path(path: &str) -> bool {
    path_set().is_match(path)
}

const HEADER_SCAN_CHARS: usize = 8192;
const HEADER_SCAN_LINES: usize = 60;

fn content_patterns() -> &'static Vec<Regex> {
    static PATTERNS: OnceLock<Vec<Regex>> = OnceLock::new();
    PATTERNS.get_or_init(|| {
        [
            r"(?i)\bcode generated\b.{0,200}?\bdo not edit\b",
            r"(?i)\b(?:automatically |auto[- ]?)?generated (?:by|from|with)\b.{0,200}?\bdo not (?:edit|modify|change)\b",
            r"(?:^|[^\p{L}\p{N}_@])@generated\b",
            r"(?i)<auto-?generated\s*/?>",
            r"(?i)\b(?:automatically generated|auto[- ]?generated|autogenerated) by\b",
            r"(?i)\bgenerated by\s+\S.{0,80}?\bby running\b",
            r"(?i)\bthis (?:file|class|code|module) (?:is|was) (?:auto[- ]?)?generated\b",
            r"(?i)\bdo not (?:edit|modify)\b.{0,120}?\b(?:auto[- ]?generated|generated file|generated code)\b",
        ]
        .iter()
        .map(|p| Regex::new(p).expect("generated header pattern"))
        .collect()
    })
}

fn comment_leader() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r#"(?i)^\s*(?://|/\*+|\*+/?|#+|--+|<!--|%+|;+|'|!|\(\*|\{-|"""|'''|=begin|<#|@rem\b|rem\b)"#).expect("comment leader"))
}

const BLOCK_DELIMS: [(&str, &str); 6] = [("/*", "*/"), ("<!--", "-->"), ("\"\"\"", "\"\"\""), ("'''", "'''"), ("=begin", "=end"), ("<#", "#>")];

/// Banner in the head of the file ("Code generated ... DO NOT EDIT.", `@generated`, ...).
pub fn has_generated_header(content: &str) -> bool {
    if content.is_empty() {
        return false;
    }
    let mut end = content.len().min(HEADER_SCAN_CHARS);
    while !content.is_char_boundary(end) {
        end -= 1;
    }
    let head = &content[..end];
    // Cheap pre-filter: every marker contains the stem "generat".
    if !head.to_ascii_lowercase().contains("generat") {
        return false;
    }
    let leader = comment_leader();
    let patterns = content_patterns();
    let mut open: Option<(&str, &str)> = None;
    for line in head.split('\n').take(HEADER_SCAN_LINES) {
        let in_block = open.is_some();
        if (in_block || leader.is_match(line)) && patterns.iter().any(|p| p.is_match(line)) {
            return true;
        }
        if let Some((_, close)) = open {
            if line.contains(close) {
                open = None;
            }
            continue;
        }
        for (o, c) in BLOCK_DELIMS {
            if let Some(at) = line.find(o) {
                if !line[at + o.len()..].contains(c) {
                    open = Some((o, c));
                }
                break;
            }
        }
    }
    false
}

const MINIFIED_LINE_CHARS: usize = 400;
const MINIFIED_MIN_BYTES: usize = 4_000;

/// A minified or bundled script that is not named so (webpack runtime, Closure/Emscripten
/// output, or most of the text on long lines dense with executable JS syntax `;{}()`).
/// Ignores string/template literals and comments so hand-written modules carrying large
/// embedded CSS/HTML/SVG/numeric lookup tables are never misclassified as minified code.
pub fn is_minified_content(path: &str, content: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    let scriptish = lower.ends_with(".js") || lower.ends_with(".mjs") || lower.ends_with(".cjs");
    if !scriptish || content.len() < MINIFIED_MIN_BYTES {
        return false;
    }
    let bytes = content.as_bytes();
    let n = bytes.len();
    let mut long_code_bytes = 0usize;
    let mut code_punct = 0usize;
    let mut in_block_comment = false;
    let mut in_template = false;
    let mut i = 0usize;
    while i < n {
        let line_start = i;
        while i < n && bytes[i] != b'\n' {
            i += 1;
        }
        let line_end = i;
        if i < n {
            i += 1; // skip '\n'
        }
        let line = &bytes[line_start..line_end];
        let is_long = line.len() >= MINIFIED_LINE_CHARS;
        let mut quote: u8 = 0; // b'\'' or b'"' (single-line strings)
        let mut j = 0usize;
        let mut line_code_bytes = 0usize;
        let mut line_punct = 0usize;
        while j < line.len() {
            let b = line[j];
            if in_block_comment {
                if b == b'*' && j + 1 < line.len() && line[j + 1] == b'/' {
                    in_block_comment = false;
                    j += 2;
                } else {
                    j += 1;
                }
                continue;
            }
            if in_template {
                if b == b'\\' {
                    j += 2;
                } else if b == b'`' {
                    in_template = false;
                    j += 1;
                } else {
                    j += 1;
                }
                continue;
            }
            if quote != 0 {
                if b == b'\\' {
                    j += 2;
                } else if b == quote {
                    quote = 0;
                    j += 1;
                } else {
                    j += 1;
                }
                continue;
            }
            if b == b'/' && j + 1 < line.len() {
                if line[j + 1] == b'/' {
                    break; // rest of line is a line comment
                }
                if line[j + 1] == b'*' {
                    in_block_comment = true;
                    j += 2;
                    continue;
                }
            }
            if b == b'\'' || b == b'"' {
                quote = b;
                j += 1;
                continue;
            }
            if b == b'`' {
                in_template = true;
                j += 1;
                continue;
            }
            // Executable code outside literals/comments: check webpack runtime signature too.
            if b == b'f' && line[j..].starts_with(b"function __webpack_require__") {
                return true;
            }
            if is_long {
                line_code_bytes += 1;
                if matches!(b, b';' | b'{' | b'}' | b'(' | b')') {
                    line_punct += 1;
                }
            }
            j += 1;
        }
        if is_long && line_code_bytes >= MINIFIED_LINE_CHARS {
            long_code_bytes += line_code_bytes;
            code_punct += line_punct;
        }
    }
    long_code_bytes as f64 >= n as f64 * 0.5 && code_punct as f64 >= long_code_bytes as f64 * 0.02
}

/// Path-only check for minified JavaScript bundles (`*.min.js`, `*-min.mjs`, `*.min.cjs`).
pub fn is_minified_path(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    lower.ends_with(".min.js")
        || lower.ends_with("-min.js")
        || lower.ends_with(".min.mjs")
        || lower.ends_with("-min.mjs")
        || lower.ends_with(".min.cjs")
        || lower.ends_with("-min.cjs")
}

/// True for minified or compiled JS bundles (`*.min.js`, webpack runtimes, Emscripten output)
/// whose obfuscated single-line bodies should stay as file nodes without AST extraction.
pub fn is_minified_script(path: &str, content: &str) -> bool {
    is_minified_path(path) || is_minified_content(path, content)
}

pub fn detect_generated(path: &str, content: &str) -> bool {
    is_generated_path(path) || has_generated_header(content) || is_minified_content(path, content)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn path_patterns() {
        assert!(is_generated_path("api/foo.pb.go"));
        assert!(is_generated_path("web/app.min.js"));
        assert!(is_generated_path("x/service_pb2.py"));
        assert!(!is_generated_path("src/main.go"));
    }

    #[test]
    fn headers() {
        assert!(has_generated_header("// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n"));
        assert!(has_generated_header("/* @generated */\nexport const x = 1;"));
        assert!(has_generated_header("# This file was auto-generated by tool\nx = 1\n"));
        assert!(!has_generated_header("package main\n// regular file\nfunc generateThing() {}\n"));
        assert!(!has_generated_header(""));
    }

    #[test]
    fn minified() {
        let long = format!("{}\n", "a(b);".repeat(1000));
        assert!(is_minified_content("x.js", &long));
        assert!(!is_minified_content("x.ts", &long));
        assert!(!is_minified_content("x.js", "const a = 1;\n"));
        // Closure-wrapped ~500-char lines (e.g. Emscripten ammo.wasm.js)
        let wrapped = format!("{}\n", format!("{}\n", "var a=f(b);".repeat(45)).repeat(10));
        assert!(is_minified_content("ammo.wasm.js", &wrapped));
        // Hand-written numeric lookup table (many commas, no `;{}()` code density) must NOT match.
        let lut = format!("export const LUT = [{}];\nexport function init() {{ return LUT[0]; }}\n", "0.123456,".repeat(1000));
        assert!(!is_minified_content("RectAreaLightUniformsLib.js", &lut));
        // Normal JS module embedding a large single-line minified CSS template literal must NOT match.
        let css = ".btn{color:red;padding:4px 8px;border:1px solid #ccc;}".repeat(120);
        let css_mod = format!("const STYLES = `{css}`;\nexport function Button() {{ return STYLES; }}\n");
        assert!(!is_minified_content("button.js", &css_mod));
    }
}
